// All calls to the FastAPI backend. No AWS credentials ever live in the browser:
// the browser only receives short-lived S3 presigned URLs generated by the backend.
const envBase = import.meta.env.VITE_API_BASE_URL
export const API_BASE = (envBase === undefined ? 'http://localhost:8000' : envBase).replace(/\/$/, '')

async function request(path, options = {}) {
  let res
  try {
    res = await fetch(`${API_BASE}${path}`, {
      headers: { 'Content-Type': 'application/json' },
      ...options,
    })
  } catch {
    throw new Error(
      `Cannot reach the backend at ${API_BASE || window.location.origin}. ` +
      'Check that it is running, the URL in VITE_API_BASE_URL is correct, and CORS_ORIGINS includes this site.',
    )
  }
  const text = await res.text()
  let body = null
  try { body = text ? JSON.parse(text) : null } catch { body = text }
  if (!res.ok) {
    const detail = body?.detail
    const msg = Array.isArray(detail) ? detail.map((d) => d.msg).join('; ') : detail || `HTTP ${res.status}`
    throw new Error(msg)
  }
  return body
}

/** Turns a backend-relative path (/api/files/...) into an absolute URL; S3 URLs pass through. */
export const absoluteUrl = (url) => (url?.startsWith('/') ? `${API_BASE}${url}` : url)

export const api = {
  health: () => request('/api/health'),
  predict: (payload) => request('/api/predict', { method: 'POST', body: JSON.stringify(payload) }),
  tasks: (id) => request(`/api/tasks/${id}`),
  results: (id) => request(`/api/results/${id}`),
  downloads: (id) => request(`/api/results/${id}/downloads`),
  structureUrl: (id) => `${API_BASE}/api/results/${id}/structure`,
  history: () => request('/api/history'),
  deleteJob: (id) => request(`/api/history/${id}`, { method: 'DELETE' }),
  benchmark: (payload) => request('/api/benchmark', { method: 'POST', body: JSON.stringify(payload) }),
}

// Remember the most recent job so sidebar links work. Storage can be unavailable -> ignore.
export function rememberJob(id) {
  try { localStorage.setItem('lastJobId', id) } catch { /* ignore */ }
}
export function lastJob() {
  try { return localStorage.getItem('lastJobId') } catch { return null }
}
